"""Generate README.md from the result files. Do not edit README.md by hand.

Usage: python -m fcp.readme
"""

import json
import os

from fcp.fetch import MANIFEST, ROOT
from fcp.learn import results_path
from fcp.sources import NOT_COVERED, REJECTED, SOURCES
from fcp.stats import CORR_OUT, SUMMARY_OUT

README = os.path.join(ROOT, "README.md")
ROUNDTRIP = os.path.join(ROOT, "results", "hydradb_float_roundtrip.json")


def load(p):
    with open(p, encoding="utf-8") as f:
        return json.load(f)


def f2(v):
    return "%.2f" % v


def render():
    r = load(results_path())
    s = load(SUMMARY_OUT)
    corr = load(CORR_OUT)
    man = {e["id"]: e for e in load(MANIFEST)["files"]}
    rt = load(ROUNDTRIP) if os.path.exists(ROUNDTRIP) else None
    sc = r["scores_co2"]
    ex = s["excluding_2020_2021"]
    hy = r["hydradb"]
    t = r["tuning"]
    names = [("graph", "HydraDB graph, refit every year"), ("no_change", "No change"),
             ("knn", "Vector-store k-NN (k=%d, window %s)" % (t["knn_k"], t["knn_window"] or "all")),
             ("frozen_graph", "Frozen graph (weights fixed after 2004)"), ("direct_regression", "Direct regression, no graph (reported only)")]
    L = []
    a = L.append
    a("# Fuel, Cars & Pollution: a HydraDB graph that refits its own links every year")
    a("")
    a("HydraDB Hackathon, Track 1 (\"a graph that improves itself, sharper every run\").")
    a("")
    a("Crude oil → gasoline → fuel use → U.S. transport CO2, with miles driven and electric-car adoption feeding in. "
      "Each link's strength is stored in a self-hosted HydraDB graph and refit every year, so each correction changes the next prediction. "
      "It is tested walk-forward, on years not used to design it, against a vector-store-style k-nearest-neighbour lookup and a \"no change\" guess.")
    a("")
    a("- Live app: not deployed yet (static site in `site/`).")
    a("- Walkthrough video: not recorded yet.")
    a("")
    a("> README generated by `python -m fcp.readme` from `results/*.json`. Do not edit numbers by hand.")
    a("")
    a("## Result first, weaknesses first")
    a("")
    a("**Pre-registered verdict: %s** (all four parts; rule in [PREREGISTRATION.md](PREREGISTRATION.md), committed before any run: `%s`)." % (
        r["verdict"], (r["preregistration_commit"] or "").split(" ")[0][:12]))
    a("")
    a("Before reading that as a win:")
    a("")
    def vs(m):
        return ("**loses** to" if ex["graph"] > ex[m] else "beats") + " %s (%s)" % ({"no_change": "no change", "knn": "k-NN", "frozen_graph": "its frozen version"}[m], f2(ex[m]))
    a("- **Without 2020 and 2021** (n = %d) the graph's MAE is %s pp: it %s, %s, and %s." % (
        ex["n"], f2(ex["graph"]), vs("no_change"), vs("knn"), vs("frozen_graph")))
    b = r["bootstrap_95"]
    zero = all(v["low"] <= 0 <= v["high"] for v in b.values())
    a("- **%s 95%% bootstrap interval of the MAE difference includes zero** (graph minus no change %s to %s; minus k-NN %s to %s; minus frozen %s to %s). n = %d holdout years." % (
        "Every" if zero else "Not every",
        f2(b["graph_minus_no_change"]["low"]), f2(b["graph_minus_no_change"]["high"]), f2(b["graph_minus_knn"]["low"]), f2(b["graph_minus_knn"]["high"]),
        f2(b["graph_minus_frozen_graph"]["low"]), f2(b["graph_minus_frozen_graph"]["high"]), s["holdout_n"]))
    a("- Year by year the graph beats no change in %d of %d years and k-NN in %d of %d." % (
        s["graph_wins_by_year"]["no_change"], s["holdout_n"], s["graph_wins_by_year"]["knn"], s["holdout_n"]))
    a("- Largest misses: %s. The 2008 recession was not visible in prices and miles driven." % ", ".join(
        "%d (%s pp)" % (e["year"], f2(e["abs_error"])) for e in s["largest_graph_errors"]))
    a("- The EV share → fuel use link is not identified: learned from %d years, its weight swung between %s and %s after 2012." % (
        s["ev_link_weight_range_2012_on"]["ev_years_used"], f2(s["ev_link_weight_range_2012_on"]["min"]), f2(s["ev_link_weight_range_2012_on"]["max"])))
    a("- Parity between HydraDB and the in-memory store passed the 1e-9 limit but is **not bit-identical**: max difference %.3g pp over %d predictions%s." % (
        hy["parity"]["max_abs_diff"], hy["parity"]["compared_values"],
        (" (HydraDB returned %d of %d test floats one ULP off; see below)" % (rt["mismatches"], rt["values_tested"])) if rt else ""))
    a("- 2009 and 2010 are not scored: FHWA marks 2009 vehicle-miles as unavailable.")
    a("")
    a("| Model | Holdout MAE (pp) | n | Without 2020–21 (n=%d) | Design MAE (n=%d) |" % (ex["n"], sc["graph"]["design_n"]))
    a("|---|---:|---:|---:|---:|")
    for k, label in names:
        a("| %s | %s | %d | %s | %s |" % (label, f2(sc[k]["holdout_mae"]), sc[k]["holdout_n"], f2(ex[k]), f2(sc[k]["design_mae"])))
    a("")
    a("MAE of the predicted yearly change in U.S. transportation-sector CO2 (EIA), in percentage points of 100·ln change. "
      "Design years 1982–2004 picked the settings (λ = %s for the graph; k = %d, window = %s for k-NN); holdout years 2005–2024 were scored once." % (
          t["graph_lambda"], t["knn_k"], t["knn_window"] or "all"))
    a("")
    a("| Rule part | Threshold | Value | Margin | Result |")
    a("|---|---|---:|---:|---|")
    for p in r["rule"]:
        val = ("%.3g" % p["value"]) if p["part"] == 1 else f2(p["value"])
        mar = ("%.3g" % p["margin"]) if p["part"] == 1 else f2(p["margin"])
        a("| %d. %s | %s | %s | %s | %s |" % (p["part"], p["name"], p["threshold"], val, mar, "PASS" if p["pass"] else "FAIL"))
    a("")
    sec = r["secondary_targets"]
    a("Secondary targets (graph vs no change, holdout MAE): fuel use %s vs %s (n=%d); gasoline price from crude %s vs %s (n=%d)." % (
        f2(sec["FuelUse"]["graph_holdout_mae"]), f2(sec["FuelUse"]["no_change_holdout_mae"]), sec["FuelUse"]["n"],
        f2(sec["Gasoline"]["graph_holdout_mae"]), f2(sec["Gasoline"]["no_change_holdout_mae"]), sec["Gasoline"]["n"]))
    a("")
    a("## What it is")
    a("")
    a("A nowcast: when a year closes, the graph estimates how much U.S. transport CO2 changed, before the official figure is final. "
      "It knows that year's crude oil price, gasoline price, vehicle-miles and the electric share of new car sales. It does not know fuel use or CO2 yet.")
    a("")
    a("1. **Predict.** Query HydraDB for the links pointing into `FuelUse`, read their weights, predict fuel use; then read the links into `CO2` and push the predicted fuel use one more hop.")
    a("2. **Correct.** When the real figures arrive, refit each target's weights by recursive least squares with forgetting, and write them back to HydraDB with a per-year history node.")
    a("3. **Repeat** next year with the corrected weights.")
    a("")
    a("The site also shows the data behind it (fuel prices, miles driven, vehicles per 1,000 people, EV share, transport CO2 and highway-vehicle pollutants) and correlations of year-over-year changes.")
    a("")
    a("## How HydraDB is used")
    a("")
    a("- Engine: `hydra-db/hydradb` v0.4.0 `graph-node`, self-hosted, local mode (`CLOUD_PROVIDER=local`), started by `scripts/run_hydradb.sh` with a new empty store, a new random token, `GRAPH_USAGE_REPORT_ENABLED=false`, and all listeners bound to 127.0.0.1. The engine is not in this repository.")
    a("- Graph: `Variable` nodes (Crude, Gasoline, VMT, EVShare, FuelUse, CO2); `Link` nodes holding the learned weight; `Fit` nodes holding each target's intercept and RLS covariance; `LinkState` history nodes (one per link per year); `Prediction` nodes. Edges: `FEEDS`, `INTO`, `FITS`, `HISTORY`, `OF`.")
    a("- Links are nodes because v0.4.0 deduplicates edges on (source, target, type): an edge cannot carry a weight that changes and keeps history.")
    a("- Each prediction is a graph walk: `MATCH (t {id: $id})<-[:INTO]-(s) RETURN s.id`, then anchored id reads of each link and fit node.")
    a("- Writes use the documented shapes: `UNWIND $rows AS row MERGE (n {id: row.id}) SET n:Label, n.p = row.p` for nodes (labels cannot sit in an UNWIND pattern), `UNWIND … CREATE` for edges, `MATCH (n {id: $id}) SET …` for updates.")
    a("- This run: %d HTTP queries in %s s; graph after the run: %s." % (hy["http_requests"], hy["seconds"], ", ".join("%d %s" % (v, k) for k, v in hy["node_counts"].items())))
    a("- Same code on an in-memory store gives the parity check.")
    a("")
    a("Engine notes found while building (v0.4.0):")
    a("")
    a("- `graph-node` binds to 0.0.0.0 by default; `GRAPH_HTTP_ADDR`, `GRAPH_BOLT_ADDR` and `GRAPH_ADMIN_ADDR` set it to loopback.")
    if rt:
        a("- Floats do not always round-trip exactly: %d of %d test values came back one ULP off (`results/hydradb_float_roundtrip.json`). Over 48 refits this left a %.3g pp gap between the HydraDB and in-memory predictions. Storing exact bit patterns (for example hex strings) would make parity exact." % (
            rt["mismatches"], rt["values_tested"], hy["parity"]["max_abs_diff"]))
    a("- `count(n)` is rejected; `count(*)` and `count(n.prop)` work.")
    a("- Node ids must be non-negative integers.")
    a("")
    a("## Pre-registered rule")
    a("")
    a("Full text: [PREREGISTRATION.md](PREREGISTRATION.md). It was committed before the first run and not edited afterwards. PASS needs all four:")
    a("")
    a("1. HydraDB and in-memory predictions agree within 1e-9 pp.")
    a("2. Graph holdout MAE ≤ 0.90 × no-change MAE.")
    a("3. Graph holdout MAE ≤ 0.90 × k-NN MAE.")
    a("4. Graph holdout MAE < frozen-graph MAE (refitting must help).")
    a("")
    a("Run history, for honesty: the first two attempts crashed in the HydraDB step (a batching bug in this project's store code, then `count(n)` being unsupported) before any holdout score was computed or printed. The fixes did not touch the method. The third attempt is the result above.")
    a("")
    a("## Correlations (year-over-year changes)")
    a("")
    a("Co-movement only; not cause. Flagged values excluded; same region and years.")
    a("")
    a("| X | Y | Region | n | Years | Pearson r | Spearman ρ |")
    a("|---|---|---|---:|---|---:|---:|")
    for c in corr:
        a("| %s | %s | %s | %d | %s–%s | %s | %s |" % (c["x_label"], c["y_label"], c["region"], c["n"], c["first_year"], c["last_year"],
                                                       f2(c["pearson_r"]) if "pearson_r" in c else "n/a", f2(c["spearman_rho"]) if "spearman_rho" in c else "n/a"))
    a("")
    a("## Data")
    a("")
    a("Every number comes from a downloaded file; URL, retrieval time and SHA-256 are in `data/manifest.json`, and `tests/test_data.py` re-reads the raw files.")
    a("")
    a("| Source | Licence | Retrieved (UTC) | SHA-256 |")
    a("|---|---|---|---|")
    for src in SOURCES:
        m = man[src["id"]]
        a("| [%s](%s) | %s | %s | `%s…` |" % (src["title"], src["url"], src["licence"], m["retrieved_at_utc"], m["sha256"][:16]))
    a("")
    a("Flags: the latest year of each EIA Monthly Energy Review table is marked provisional; EPA highway-vehicle values for 2024–2025 are marked carried forward (EPA's workbook notes say those years repeat the 2023 inventory for non-power-plant sources; a test checks they equal 2023); calendar years with fewer than 12 months of Ember data are marked partial. Flagged values are shown but left out of correlations and scoring.")
    a("")
    a("Considered and not used:")
    a("")
    for x in REJECTED:
        a("- **%s**: %s" % (x["name"], x["reason"]))
    a("")
    a("Not covered:")
    a("")
    for x in NOT_COVERED:
        a("- **%s**: %s" % (x["item"], x["why"]))
    a("")
    a("## Limitations")
    a("")
    a("- Small sample: %d holdout years; the intervals above are wide." % s["holdout_n"])
    a("- The author knew the broad history of the holdout years (2008, 2020) even though settings were picked on 1982–2004 only.")
    a("- Nowcasting is narrow: EIA publishes the real CO2 figure within months. The value shown is the learning loop, not a forecast product.")
    a("- U.S. only for the learning loop. World series are shown but not modelled.")
    a("- The \"what the links imply\" calculator on the site is arithmetic on the final weights; it was not tested as a scenario model.")
    a("- The k-NN baseline is one reasonable plain-store design (same inputs, standardised, RMS distance over shared dimensions). Other designs could score differently.")
    a("")
    a("## Reproduce")
    a("")
    a("```bash")
    a("python -m pip install -r requirements.txt")
    a("python -m fcp.fetch        # download files, write data/manifest.json")
    a("python -m fcp.parse        # data/processed/series.json")
    a("bash scripts/run_hydradb.sh <path-to-graph-node> .hydradb/token   # inside WSL/Linux, separate shell")
    a("python -m fcp.experiment   # pre-registered run -> results/learning_results.json")
    a("python -m fcp.roundtrip    # float round-trip check")
    a("python -m fcp.stats        # correlations and summary")
    a("python -m fcp.site         # static site in site/")
    a("python -m fcp.readme       # this file")
    a("python -m pytest -q        # tests, data check, privacy scan")
    a("```")
    a("")
    a("Re-downloading gives today's files; the committed raw files and their hashes are what these results used.")
    a("")
    a("## Licence")
    a("")
    a("Code: MIT (see `LICENSE`). Data keeps its own licence (see the table above). HydraDB is Elastic License 2.0 and is not included or redistributed.")
    a("")
    return "\n".join(L)


def main():
    with open(README, "w", encoding="utf-8", newline="\n") as f:
        f.write(render())
    print("README.md written")


if __name__ == "__main__":
    main()
